-- Arbeitsrecht Berufsbildung > Kündigungsschutz > Kündigungsfristen (§ 22 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss eine Kündigung eines Fachinformatikers nach der Probezeit eine Frist von 4 Wochen einhalten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG legt 4 Wochen zum Monatsende fest"}, {"text": "Nein", "correct": false, "because": "Frist ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker in der Probezeit mit einer Frist von 2 Wochen kündigen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 1 BBiG erlaubt dies in der Probezeit"}, {"text": "Nein", "correct": false, "because": "2 Wochen sind zulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine außerordentliche Kündigung eines Fachinformatikers eine Kündigungsfrist einhalten?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 Abs. 2 BBiG erlaubt fristlose Kündigung bei wichtigem Grund"}, {"text": "Ja", "correct": false, "because": "Fristlosigkeit ist bei außerordentlicher Kündigung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Betrieb einen Fachinformatiker nach der Probezeit ohne Einhaltung einer Frist kündigen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt Fristen bei ordentlicher Kündigung"}, {"text": "Ja", "correct": false, "because": "Fristen sind vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Kündigungsfrist eines Fachinformatikers in der Probezeit kürzer als nach der Probezeit?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 1 BBiG legt 2 Wochen in der Probezeit fest, danach 4 Wochen"}, {"text": "Nein", "correct": false, "because": "Probezeitfrist ist kürzer"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage definiert die Kündigungsfristen für einen Fachinformatiker?', 2, '[{"text": "§ 22 BBiG", "correct": true, "because": "Regelt Kündigungsfristen im BBiG"}, {"text": "§ 15 BBiG", "correct": false, "because": "Bezieht sich auf Berufsschule"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie lange beträgt die Kündigungsfrist für eine ordentliche Kündigung eines Fachinformatikers nach der Probezeit?', 3, '[{"text": "4 Wochen zum Monatsende", "correct": true, "because": "§ 22 Abs. 2 BBiG legt dies fest"}, {"text": "2 Wochen jederzeit", "correct": false, "because": "Nur in der Probezeit"}, {"text": "Sofort ohne Frist", "correct": false, "because": "Fristen sind vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kündigungsfrist gilt für einen Fachinformatiker in der Probezeit?', 2, '[{"text": "2 Wochen", "correct": true, "because": "§ 22 Abs. 1 BBiG definiert dies"}, {"text": "1 Monat", "correct": false, "because": "Zu lang für Probezeit"}, {"text": "4 Wochen", "correct": false, "because": "Gilt nach Probezeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer legt die Kündigungsfrist für eine ordentliche Kündigung eines Fachinformatikers nach der Probezeit fest?', 3, '[{"text": "Das BBiG", "correct": true, "because": "§ 22 Abs. 2 BBiG bestimmt die Frist"}, {"text": "Der Betrieb", "correct": false, "because": "Frist ist gesetzlich geregelt"}, {"text": "Die IHK", "correct": false, "because": "IHK überwacht nur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb die Kündigungsfrist eines Fachinformatikers nach der Probezeit nicht einhält?', 3, '[{"text": "Die Kündigung ist unwirksam", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt Fristeinhaltung"}, {"text": "Die Kündigung gilt trotzdem", "correct": false, "because": "Fristverstoß macht sie unwirksam"}, {"text": "Die IHK übernimmt die Kündigung", "correct": false, "because": "IHK hat keine Rolle dabei"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kündigungsfristen gelten für einen Fachinformatiker gemäß § 22 BBiG?', 4, '[{"text": "2 Wochen in der Probezeit", "correct": true, "because": "§ 22 Abs. 1 BBiG legt dies fest"}, {"text": "4 Wochen zum Monatsende nach der Probezeit", "correct": true, "because": "§ 22 Abs. 2 BBiG definiert dies"}, {"text": "1 Woche jederzeit", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Fristlos bei wichtigem Grund", "correct": true, "because": "§ 22 Abs. 2 BBiG erlaubt dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regeln müssen bei der Kündigung eines Fachinformatikers nach der Probezeit eingehalten werden?', 3, '[{"text": "Schriftform", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert dies"}, {"text": "4 Wochen Frist zum Monatsende", "correct": true, "because": "Gilt bei ordentlicher Kündigung"}, {"text": "Mündliche Mitteilung", "correct": false, "because": "Schriftform ist Pflicht"}, {"text": "Angabe eines wichtigen Grundes", "correct": true, "because": "Erforderlich nach Probezeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gilt für die Kündigungsfrist eines Fachinformatikers in der Probezeit?', 4, '[{"text": "2 Wochen Frist", "correct": true, "because": "§ 22 Abs. 1 BBiG legt dies fest"}, {"text": "Keine Begründung erforderlich", "correct": true, "because": "Probezeit erfordert keinen Grund"}, {"text": "4 Wochen Frist", "correct": false, "because": "Gilt nach Probezeit"}, {"text": "Jederzeit ohne Frist möglich", "correct": false, "because": "2 Wochen sind vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen hat eine Kündigung eines Fachinformatikers ohne Einhaltung der Frist?', 3, '[{"text": "Die Kündigung ist unwirksam", "correct": true, "because": "§ 22 BBiG verlangt Fristeinhaltung"}, {"text": "Der Auszubildende kann Klage erheben", "correct": true, "because": "Rechtsschutz möglich"}, {"text": "Die Kündigung gilt automatisch", "correct": false, "because": "Fristverstoß macht sie ungültig"}, {"text": "Die IHK entscheidet darüber", "correct": false, "because": "IHK hat keine direkte Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'In welchen Fällen gilt keine Kündigungsfrist für einen Fachinformatiker?', 3, '[{"text": "Bei außerordentlicher Kündigung mit wichtigem Grund", "correct": true, "because": "§ 22 Abs. 2 BBiG erlaubt Fristlosigkeit"}, {"text": "Bei schwerwiegendem Fehlverhalten", "correct": true, "because": "Wichtiger Grund rechtfertigt dies"}, {"text": "Bei jeder Kündigung nach der Probezeit", "correct": false, "because": "Ordentliche Kündigung hat Frist"}, {"text": "Bei Betriebsstilllegung", "correct": true, "because": "Kann wichtiger Grund sein"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Kündigungsfrist in der Probezeit beträgt 2 Wochen. b) Nach der Probezeit beträgt die Frist 4 Wochen zum Monatsende.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 22 Abs. 1 und 2 BBiG bestätigen dies"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine außerordentliche Kündigung eines Fachinformatikers erfordert keine Frist. b) Eine ordentliche Kündigung in der Probezeit hat eine Frist von 4 Wochen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fristlos möglich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Kündigungsfrist nach der Probezeit beträgt 4 Wochen. b) In der Probezeit ist keine Kündigungsfrist vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "4 Wochen korrekt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker kann in der Probezeit mit 2 Wochen Frist kündigen. b) Nach der Probezeit gilt keine Kündigungsfrist.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2 Wochen in Probezeit, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Kündigungsfrist für eine ordentliche Kündigung nach der Probezeit ist 4 Wochen zum Monatsende. b) Eine fristlose Kündigung erfordert eine Frist von 2 Wochen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "4 Wochen korrekt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

